/**
 * LRU cache with TTL. Entries expire after ttlMs; the cache holds at most
 * `capacity` entries and evicts the least-recently-used one when full.
 */
export function createCache({ ttlMs, capacity, clock = () => Date.now() }) {
  const entries = new Map() // key -> { value, expiresAt, lastUsed }, Map order = recency order (oldest first)
  return {
    get(key) {
      const entry = entries.get(key)
      if (entry === undefined) return undefined
      const now = clock()
      if (now > entry.expiresAt) {
        entries.delete(key)
        return undefined
      }
      entry.lastUsed = now
      // move to the most-recently-used end
      entries.delete(key)
      entries.set(key, entry)
      return entry.value
    },
    set(key, value) {
      const now = clock()
      if (entries.size >= capacity && !entries.has(key)) {
        // evict the least-recently-used entry (first in recency order)
        const oldestKey = entries.keys().next().value
        entries.delete(oldestKey)
      }
      // refresh recency: an existing key becomes the most-recently-used entry
      entries.delete(key)
      entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
    },
    size() {
      return entries.size
    },
    _raw() {
      return [...entries.entries()]
    },
  }
}

